proposed=s
for patch in patches:proposed=proposed.replace(patch['old_text'],patch['new_text'],1)
for marker in [r'\tag{',r'\begin{proof}',r'\end{proof}',r'\label{']:
 if marker in (r'\tag{',r'\label{'):
  assert re.findall(re.escape(marker)+r'([^}]*)}',s)==re.findall(re.escape(marker)+r'([^}]*)}',proposed)
 else:assert s.count(marker)==proposed.count(marker)
(p/'IV_low_F_computation_patches.json').write_text(json.dumps(patches,ensure_ascii=False,indent=2)+'\n')
receipt={'source':str(source),'source_sha256':hashlib.sha256(s.encode()).hexdigest(),'patch_count':len(patches),'all_old_text_unique':True,'equation_tag_order_preserved':True,'all_labels_preserved':True,'proof_balance_preserved':True,'displaced_execution_history':patches,'integration':'Proposal only. Root owns integration; no shared body was changed.'}
(p/'IV_low_F_computation_patch_receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:receipt[k] for k in ['patch_count','all_old_text_unique','equation_tag_order_preserved','all_labels_preserved','proof_balance_preserved']}))
